using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Game.Map;
using Game.Stage;

namespace Game.Tests
{
    /// <summary>
    /// ステージ管理システムの生成、進行、
    /// 宝石取得、壁破壊などを検証するテストクラス。
    /// </summary>
    public class MazeStageManagerTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト対象")]

        /// <summary>
        /// テスト対象のステージ管理システム。
        /// </summary>
        [SerializeField]
        private MazeStageManager stageManager;

        [Header("テスト設定")]

        /// <summary>
        /// シーン開始時に自動テストを実行するか。
        /// </summary>
        [SerializeField]
        private bool runTestsOnStart = false;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// 成功したテスト項目数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目数。
        /// </summary>
        private int failedCount;

        /// <summary>
        /// 自動テストの実行状態。
        /// </summary>
        private bool isTesting;

        #endregion

        #region Unity Methods

        /// <summary>
        /// シーン開始時の処理。
        /// </summary>
        private IEnumerator Start()
        {
            // StageManagerのStart処理が完了するまで待つ。
            yield return null;

            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Manual Tests

        /// <summary>
        /// ステージを再生成する。
        /// </summary>
        [ContextMenu("テスト/ステージを生成する")]
        private void GenerateStage()
        {
            if (!CanTest()) return;

            Debug.Log(
                $"生成結果：{stageManager.GenerateStage()}",
                this);
        }

        /// <summary>
        /// ステージを開始する。
        /// </summary>
        [ContextMenu("テスト/ステージを開始する")]
        private void StartStage()
        {
            if (!CanTest()) return;

            Debug.Log(
                $"開始結果：{stageManager.StartStage()}",
                this);
        }

        /// <summary>
        /// ステージを一時停止する。
        /// </summary>
        [ContextMenu("テスト/一時停止する")]
        private void PauseStage()
        {
            if (!CanTest()) return;

            Debug.Log(
                $"一時停止結果：{stageManager.PauseStage()}",
                this);
        }

        /// <summary>
        /// ステージを再開する。
        /// </summary>
        [ContextMenu("テスト/再開する")]
        private void ResumeStage()
        {
            if (!CanTest()) return;

            Debug.Log(
                $"再開結果：{stageManager.ResumeStage()}",
                this);
        }

        /// <summary>
        /// マップ上の宝石を1個取得する。
        /// </summary>
        [ContextMenu("テスト/宝石を1個取得する")]
        private void CollectGem()
        {
            if (!CanTest() || !stageManager.HasStage)
            {
                return;
            }

            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.HasGem))
            {
                bool success =
                    stageManager.TryCollectGem(position);

                Debug.Log(
                    $"取得結果：{success}\n" +
                    $"残り宝石数：{stageManager.RemainingGemCount}",
                    this);

                return;
            }
        }

        /// <summary>
        /// マップ上のアイテムを1個取得する。
        /// </summary>
        [ContextMenu("テスト/アイテムを1個取得する")]
        private void CollectItem()
        {
            if (!CanTest() || !stageManager.HasStage)
            {
                return;
            }

            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.HasItem))
            {
                bool success =
                    stageManager.TryCollectItem(position);

                Debug.Log(
                    $"取得結果：{success}\n" +
                    $"残りアイテム数：{stageManager.RemainingItemCount}",
                    this);

                return;
            }
        }

        /// <summary>
        /// 破壊可能な壁を1個破壊する。
        /// </summary>
        [ContextMenu("テスト/壁を1個破壊する")]
        private void DestroyWall()
        {
            if (!CanTest() || !stageManager.HasStage)
            {
                return;
            }

            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.IsBreakable))
            {
                bool success =
                    stageManager.TryDestroyWall(position);

                Debug.Log(
                    $"壁破壊結果：{success}\n" +
                    $"破壊座標：{position}",
                    this);

                return;
            }
        }

        /// <summary>
        /// すべての宝石を取得してクリアする。
        /// </summary>
        [ContextMenu("テスト/すべての宝石を取得する")]
        private void CollectAllGems()
        {
            if (!CanTest() || !stageManager.HasStage)
            {
                return;
            }

            CollectAllGemsInternal();

            PrintStatus();
        }

        /// <summary>
        /// ステージを失敗状態にする。
        /// </summary>
        [ContextMenu("テスト/ステージを失敗させる")]
        private void FailStage()
        {
            if (!CanTest()) return;

            Debug.Log(
                $"失敗状態への変更：{stageManager.FailStage()}",
                this);
        }

        /// <summary>
        /// 現在のステージを消去する。
        /// </summary>
        [ContextMenu("テスト/ステージを消去する")]
        private void ClearStage()
        {
            if (!CanTest()) return;

            stageManager.ClearStage();
        }

        /// <summary>
        /// 現在のステージ状態をConsoleへ出力する。
        /// </summary>
        [ContextMenu("テスト/現在の状態を表示する")]
        private void PrintStatus()
        {
            if (!CanTest()) return;

            Debug.Log(
                "【ステージ状態】\n" +
                $"状態：{stageManager.State}\n" +
                $"初期宝石数：{stageManager.InitialGemCount}\n" +
                $"残り宝石数：{stageManager.RemainingGemCount}\n" +
                $"取得宝石数：{stageManager.CollectedGemCount}\n" +
                $"残りアイテム数：{stageManager.RemainingItemCount}\n" +
                $"経過時間：{stageManager.ElapsedTime:F2}秒\n" +
                $"進捗率：{stageManager.Progress:P1}",
                this);
        }

        #endregion

        #region Automated Tests

        /// <summary>
        /// ステージ管理の自動テストを開始する。
        /// </summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        private void RunAllTests()
        {
            if (!CanTest() || isTesting)
            {
                return;
            }

            StartCoroutine(TestRoutine());
        }

        /// <summary>
        /// ステージの生成からクリアまでを検証する。
        /// </summary>
        private IEnumerator TestRoutine()
        {
            isTesting = true;

            passedCount = 0;
            failedCount = 0;

            try
            {
                // ステージ生成を検証する。
                bool generated =
                    stageManager.GenerateStage();

                Check(generated, "ステージ生成");

                if (!generated)
                {
                    yield break;
                }

                Check(
                    stageManager.HasStage,
                    "生成済みマップの存在");

                Check(
                    stageManager.State == MazeStageState.Ready,
                    "開始待機状態への移行");

                Check(
                    stageManager.RemainingGemCount ==
                    stageManager.Map.CountCells(
                        cell => cell.HasGem),
                    "初期宝石数の一致");

                Check(
                    stageManager.RemainingItemCount ==
                    stageManager.Map.CountCells(
                        cell => cell.HasItem),
                    "初期アイテム数の一致");

                // 開始前の取得禁止を確認する。
                Check(
                    !stageManager.TryCollectGem(
                        stageManager.StageResult.PlayerSpawnPosition),
                    "開始前の宝石取得禁止");

                Check(
                    stageManager.StartStage(),
                    "ステージ開始");

                Check(
                    stageManager.IsPlaying,
                    "プレイ中状態への移行");

                // 時間が進むことを確認する。
                float startTime =
                    stageManager.ElapsedTime;

                yield return new WaitForSecondsRealtime(0.2f);

                Check(
                    stageManager.ElapsedTime > startTime,
                    "プレイ時間の計測");

                // 一時停止と時間停止を確認する。
                Check(
                    stageManager.PauseStage(),
                    "一時停止");

                Check(
                    stageManager.State == MazeStageState.Paused,
                    "一時停止状態への移行");

                float pausedTime =
                    stageManager.ElapsedTime;

                yield return new WaitForSecondsRealtime(0.2f);

                Check(
                    Mathf.Approximately(
                        pausedTime,
                        stageManager.ElapsedTime),
                    "一時停止中の時間停止");

                Check(
                    stageManager.ResumeStage(),
                    "ステージ再開");

                Check(
                    stageManager.IsPlaying,
                    "プレイ中状態への復帰");

                // 宝石の取得処理を確認する。
                TestGemCollection();

                // アイテムの取得処理を確認する。
                TestItemCollection();

                // 壁の破壊処理を確認する。
                TestWallDestruction();

                // すべての宝石を取得する。
                CollectAllGemsInternal();

                Check(
                    stageManager.RemainingGemCount == 0,
                    "すべての宝石を取得");

                Check(
                    stageManager.State == MazeStageState.Cleared,
                    "ステージクリア判定");

                Check(
                    Mathf.Approximately(
                        stageManager.Progress, 1f),
                    "クリア時の進捗率");

                // クリア後の時間停止を確認する。
                float clearedTime =
                    stageManager.ElapsedTime;

                yield return new WaitForSecondsRealtime(0.2f);

                Check(
                    Mathf.Approximately(
                        clearedTime,
                        stageManager.ElapsedTime),
                    "クリア後の時間停止");

                // 再生成と初期化を確認する。
                Check(
                    stageManager.GenerateStage(),
                    "ステージ再生成");

                Check(
                    stageManager.State == MazeStageState.Ready,
                    "再生成後の開始待機状態");

                Check(
                    Mathf.Approximately(
                        stageManager.ElapsedTime, 0f),
                    "再生成後の時間初期化");

                Check(
                    stageManager.RemainingGemCount ==
                    stageManager.InitialGemCount,
                    "再生成後の宝石数初期化");

                // 失敗状態への移行を確認する。
                Check(
                    stageManager.StartStage(),
                    "再生成後のステージ開始");

                Check(
                    stageManager.FailStage(),
                    "ステージ失敗処理");

                Check(
                    stageManager.State == MazeStageState.Failed,
                    "失敗状態への移行");

                // ステージ消去を確認する。
                stageManager.ClearStage();

                Check(
                    !stageManager.HasStage,
                    "ステージデータの消去");

                Check(
                    stageManager.State == MazeStageState.None,
                    "未生成状態への移行");
            }
            finally
            {
                isTesting = false;

                PrintTestResult();
            }
        }

        /// <summary>
        /// 宝石取得と二重取得防止を検証する。
        /// </summary>
        private void TestGemCollection()
        {
            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.HasGem))
            {
                int previousCount =
                    stageManager.RemainingGemCount;

                Check(
                    stageManager.TryCollectGem(position),
                    "宝石取得処理");

                Check(
                    stageManager.RemainingGemCount ==
                    previousCount - 1,
                    "宝石残数の減算");

                Check(
                    !stageManager.Map.GetCell(position).HasGem,
                    "マップ上の宝石消去");

                Check(
                    !stageManager.TryCollectGem(position),
                    "宝石の二重取得防止");

                return;
            }

            Debug.LogWarning(
                "宝石がないため取得テストを省略します。",
                this);
        }

        /// <summary>
        /// アイテム取得と候補属性の維持を検証する。
        /// </summary>
        private void TestItemCollection()
        {
            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.HasItem))
            {
                int previousCount =
                    stageManager.RemainingItemCount;

                Check(
                    stageManager.TryCollectItem(position),
                    "アイテム取得処理");

                Check(
                    stageManager.RemainingItemCount ==
                    previousCount - 1,
                    "アイテム残数の減算");

                Check(
                    !stageManager.Map.GetCell(position).HasItem,
                    "マップ上のアイテム消去");

                Check(
                    stageManager.Map.GetCell(position).IsItemSpawn,
                    "アイテム配置候補属性の維持");

                Check(
                    !stageManager.TryCollectItem(position),
                    "アイテムの二重取得防止");

                return;
            }

            Debug.LogWarning(
                "アイテムがないため取得テストを省略します。",
                this);
        }

        /// <summary>
        /// 壁の破壊と移動可能状態への変化を検証する。
        /// </summary>
        private void TestWallDestruction()
        {
            foreach (Vector2Int position in
                stageManager.Map.FindPositions(
                    cell => cell.IsBreakable))
            {
                Check(
                    !stageManager.IsWalkable(position),
                    "破壊前の壁への移動禁止");

                Check(
                    stageManager.TryDestroyWall(position),
                    "壁破壊処理");

                Check(
                    stageManager.IsWalkable(position),
                    "壁破壊後の移動許可");

                Check(
                    !stageManager.TryDestroyWall(position),
                    "壁の二重破壊防止");

                Check(
                    !stageManager.TryDestroyWall(
                        Vector2Int.zero),
                    "外周の壁の破壊禁止");

                return;
            }

            Debug.LogWarning(
                "破壊可能な壁がないためテストを省略します。",
                this);
        }

        /// <summary>
        /// 現在のマップに存在する宝石をすべて取得する。
        /// </summary>
        private void CollectAllGemsInternal()
        {
            // 取得処理前に座標一覧を確定する。
            List<Vector2Int> positions =
                new List<Vector2Int>(
                    stageManager.Map.FindPositions(
                        cell => cell.HasGem));

            foreach (Vector2Int position in positions)
            {
                stageManager.TryCollectGem(position);
            }
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// テストを実行可能な状態か確認する。
        /// </summary>
        /// <returns>実行可能な場合はtrue</returns>
        private bool CanTest()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return false;
            }

            if (stageManager == null)
            {
                Debug.LogError(
                    "StageManagerが設定されていません。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// 自動テストの集計結果を出力する。
        /// </summary>
        private void PrintTestResult()
        {
            string message =
                "【MazeStageManager テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべての実行済みテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
